INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine digitale Unterschrift immer rechtlich bindend?', 2, '[{"text": "Nein", "correct": true, "because": "Nur qualifizierte Signaturen sind verbindlich"}, {"text": "Ja", "correct": false, "because": "Nicht alle erfüllen rechtliche Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die Sicherheit einer elektronischen Unterschrift entscheidend?', 3, '[{"text": "Privater Schlüssel", "correct": true, "because": "Nur der Unterzeichner hat Zugriff"}, {"text": "Öffentlicher Schlüssel", "correct": false, "because": "Dient nur zur Verifikation"}, {"text": "Hash-Algorithmus", "correct": false, "because": "Teil, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine Signatur rechtsverbindlich?', 4, '[{"text": "Zertifikat von vertrauenswürdiger Stelle", "correct": true, "because": "Bestätigt Identität"}, {"text": "Eindeutige Zuordnung zum Unterzeichner", "correct": true, "because": "Verhindert Fälschung"}, {"text": "Hohe Verschlüsselungsrate", "correct": false, "because": "Wichtig, aber nicht spezifisch"}, {"text": "Farbliche Markierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Zertifikat ist für die Gültigkeit nötig. b) Jede Signatur ist automatisch qualifiziert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) erfordert spezielle Kriterien"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung einer verbindlichen Unterschrift?', 3, '[{"text": "Zertifizierungsstelle", "correct": false, "because": "Notwendig für Vertrauen"}, {"text": "Kryptografischer Schlüssel", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Dokumentenfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein öffentlicher Schlüssel eine Signatur erstellt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur der private Schlüssel signiert"}, {"text": "Ja", "correct": false, "because": "Öffentlich, daher unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren stellt die Integrität eines signierten Dokuments sicher?', 4, '[{"text": "Hashing mit Prüfsumme", "correct": true, "because": "Erkennt Manipulationen"}, {"text": "Komprimierung", "correct": false, "because": "Verkleinert nur Dateien"}, {"text": "Verschlüsselte Übertragung", "correct": false, "because": "Schützt nur Transport"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind für eine rechtsverbindliche Unterschrift nötig?', 5, '[{"text": "Zertifikat einholen", "correct": true, "because": "Bestätigt Identität"}, {"text": "Privaten Schlüssel nutzen", "correct": true, "because": "Erstellt Signatur"}, {"text": "Dokument drucken", "correct": false, "because": "Nicht digital relevant"}, {"text": "Farbliche Markierung", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine qualifizierte Signatur braucht ein Zertifikat. b) Sie ist nur offline gültig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ignoriert digitale Nutzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine elektronische Unterschrift?', 3, '[{"text": "Privater Schlüssel", "correct": false, "because": "Erstellt die Signatur"}, {"text": "Zertifizierungsstelle", "correct": false, "because": "Liefert Vertrauen"}, {"text": "Grafische Unterschrift", "correct": true, "because": "Nur visuelle Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist jede digitale Signatur manipulationssicher?', 2, '[{"text": "Nein", "correct": true, "because": "Nur mit Hash und Schlüsselpaar"}, {"text": "Ja", "correct": false, "because": "Nicht alle sind qualifiziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie sichert die Authentizität eines Dokuments?', 4, '[{"text": "Asymmetrische Kryptografie", "correct": true, "because": "Schlüsselpaar für Signatur"}, {"text": "Symmetrische Verschlüsselung", "correct": false, "because": "Kein Identitätsnachweis"}, {"text": "Blockchain", "correct": false, "because": "Nur für Transaktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Unterschrift ohne Zertifikat rechtsverbindlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Zertifikat bestätigt Identität"}, {"text": "Ja", "correct": false, "because": "Fehlende Verifikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Signaturverfahrens?', 3, '[{"text": "Rechtliche Anerkennung", "correct": true, "because": "Sichert Verbindlichkeit"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Dateigröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein privater Schlüssel signiert. b) Ein öffentlicher Schlüssel erstellt die Signatur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, öffentlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine rechtsverbindliche Unterschrift?', 5, '[{"text": "Manipulationsschutz", "correct": true, "because": "Hash erkennt Änderungen"}, {"text": "Identitätsnachweis", "correct": true, "because": "Zertifikat bestätigt"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Kein Sicherheitsvorteil"}, {"text": "Kleinere Dateien", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer digitalen Unterschrift unwichtig?', 3, '[{"text": "Zertifizierungsstelle", "correct": false, "because": "Liefert Vertrauen"}, {"text": "Kryptografischer Algorithmus", "correct": false, "because": "Sichert Integrität"}, {"text": "Dokumentenlayout", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt eine digitale Unterschrift die handschriftliche immer?', 3, '[{"text": "Nein", "correct": true, "because": "Nur bei qualifizierter Signatur gleichwertig"}, {"text": "Ja", "correct": false, "because": "Rechtliche Unterschiede"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Hash-Algorithmus die Vertraulichkeit sichert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Integrität, nicht Verschlüsselung"}, {"text": "Ja", "correct": false, "because": "Falsche Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was tue ich, wenn ein Zertifikat abläuft?', 4, '[{"text": "Neues Zertifikat beantragen", "correct": true, "because": "Gültigkeit erforderlich"}, {"text": "Altes weiter nutzen", "correct": false, "because": "Ungültig, unsicher"}, {"text": "Signatur löschen", "correct": false, "because": "Nicht notwendig"}]');
